"""Frozen synthetic bug-fix tasks; none are published benchmark problems."""
TASKS = [
 dict(id='01-clamp', prompt='Repair clamp(value, lower, upper): include both endpoints, return the closest endpoint for an out-of-range value, and raise ValueError for reversed bounds. Support integers and floats.', code='def clamp(value, lower, upper):\n    return min(value, lower)\n', visible='assert s.clamp(5, 0, 10) == 5', checks=['assert s.clamp(-2,0,10)==0','assert s.clamp(12,0,10)==10','assert s.clamp(0,0,10)==0','assert s.clamp(10,0,10)==10','assert s.clamp(2.5,0.5,2)==2','assert s.clamp(7,3,3)==3','raises(ValueError, s.clamp, 1, 5, 2)']),
 dict(id='02-chunks', prompt='Repair chunks(values, size) to return a list of consecutive lists, retaining a final short chunk. Accept any finite iterable including a generator. Empty input returns []. Reject nonpositive size with ValueError.', code='def chunks(values, size):\n    return [values[i:i+size] for i in range(0, len(values)-size+1, size)]\n', visible='assert s.chunks([1,2,3], 2) == [[1,2],[3]]', checks=['assert s.chunks([],2)==[]','assert s.chunks([1,2],5)==[[1,2]]','assert s.chunks(range(5),2)==[[0,1],[2,3],[4]]','assert s.chunks((x for x in range(4)),3)==[[0,1,2],[3]]','raises(ValueError,s.chunks,[1],0)','raises(ValueError,s.chunks,[1],-1)']),
 dict(id='03-deep-merge', prompt='Repair deep_merge(left,right): recursively merge dictionaries, give right precedence for non-dictionary conflicts, and do not mutate or alias either input including nested lists. Return an independent result.', code='def deep_merge(left, right):\n    left.update(right)\n    return left\n', visible='assert s.deep_merge({"a":1},{"b":2}) == {"a":1,"b":2}', checks=['a={"x":{"a":1,"b":[2]}}; b={"x":{"c":3}}; r=s.deep_merge(a,b); assert r=={"x":{"a":1,"b":[2],"c":3}}','assert a=={"x":{"a":1,"b":[2]}} and b=={"x":{"c":3}}','r["x"]["b"].append(4); assert a["x"]["b"]==[2]','assert s.deep_merge({"x":{}},{"x":None})=={"x":None}','b={"x":[1]}; r=s.deep_merge({},b); r["x"].append(2); assert b=={"x":[1]}']),
 dict(id='04-boolean', prompt='Repair parse_bool(value): pass through actual booleans; for strings trim whitespace and ignore case, accepting true/yes/on/1 and false/no/off/0. Raise ValueError for any other value, including integers, None, and an empty string.', code='def parse_bool(value):\n    return bool(value)\n', visible='assert s.parse_bool("false") is False', checks=['assert all(s.parse_bool(x) is True for x in [True,"true"," YES ","on","1"])','assert all(s.parse_bool(x) is False for x in [False,"false"," NO ","off","0"])','for x in [None,0,1,[],"", "maybe"]: raises(ValueError,s.parse_bool,x)']),
 dict(id='05-moving-average', prompt='Repair moving_average(values, window): return the means of every complete consecutive window, not partial windows. Accept a finite iterable. Return [] when there are too few items. Reject a nonpositive window with ValueError.', code='def moving_average(values, window):\n    return [sum(values[:window])/window]\n', visible='assert s.moving_average([1,2,3],2)==[1.5,2.5]', checks=['assert s.moving_average([],2)==[]','assert s.moving_average([1],2)==[]','assert s.moving_average([2,4,6],1)==[2,4,6]','assert s.moving_average((x for x in [1,3,5,7]),3)==[3,5]','raises(ValueError,s.moving_average,[1],0)','raises(ValueError,s.moving_average,[1],-2)']),
 dict(id='06-stable-unique', prompt='Repair stable_unique(values) to return the first occurrence of each equality-distinct item in original order. Support unhashable items such as lists and dictionaries and finite generators. Do not modify the input.', code='def stable_unique(values):\n    return list(set(values))\n', visible='assert s.stable_unique([3,1,3,2,1])==[3,1,2]', checks=['assert s.stable_unique([[1],[1],[2]])==[[1],[2]]','assert s.stable_unique([{"a":1},{"a":1},{"b":2}])==[{"a":1},{"b":2}]','assert s.stable_unique(iter([2,1,2]))==[2,1]','assert s.stable_unique([])==[]','a=[[1],[2],[1]]; before=repr(a); s.stable_unique(a); assert repr(a)==before']),
 dict(id='07-ttl-cache', prompt='Repair TTLCache: set(key,value,ttl,now) stores a value until now+ttl; get(key,now,default=None) returns default for missing or expired entries and removes expired entries. An entry expires exactly at its deadline. ttl<=0 must not leave a usable entry. Updating a key replaces its value and deadline.', code='class TTLCache:\n    def __init__(self):\n        self.items = {}\n    def set(self, key, value, ttl, now):\n        self.items[key] = (value, now + ttl)\n    def get(self, key, now, default=None):\n        if key not in self.items:\n            return default\n        value, deadline = self.items[key]\n        return value\n', visible='c=s.TTLCache(); c.set("x",3,2,0); assert c.get("x",1)==3', checks=['c=s.TTLCache(); c.set("x",3,2,10); assert c.get("x",12,"miss")=="miss"','assert "x" not in c.items','c.set("a",1,0,5); assert c.get("a",5) is None','c.set("a",1,-1,5); assert c.get("a",5) is None','c.set("b",1,1,5); c.set("b",2,10,5); assert c.get("b",7)==2','assert c.get("absent",0,42)==42']),
 dict(id='08-csv-records', prompt='Repair read_records(text) to parse CSV text with a header into a list of dictionaries using standard CSV quoting rules. Support quoted commas, quoted newlines, CRLF line endings, and blank lines. Return [] for empty text or a header with no records. Use Python standard library only.', code='def read_records(text):\n    lines=text.splitlines()\n    keys=lines[0].split(",")\n    return [dict(zip(keys,line.split(","))) for line in lines[1:]]\n', visible='assert s.read_records("a,b\\n1,2\\n")==[{"a":"1","b":"2"}]', checks=['assert s.read_records(\'name,note\\nAlice,"hello, world"\\n\')==[{"name":"Alice","note":"hello, world"}]','assert s.read_records(\'a,b\\n"two\\nlines",x\\n\')==[{"a":"two\\nlines","b":"x"}]','assert s.read_records("a,b\\r\\n1,2\\r\\n")==[{"a":"1","b":"2"}]','assert s.read_records("")==[]','assert s.read_records("a,b\\n")==[]','assert s.read_records("a,b\\n\\n1,2\\n")==[{"a":"1","b":"2"}]']),
 dict(id='09-intervals', prompt='Repair merge_intervals(intervals): accept pairs with start<=end, sort them without changing the input, and merge overlapping or touching closed intervals. Return a list of tuples. Reject reversed intervals with ValueError. Handle empty input and nested intervals.', code='def merge_intervals(intervals):\n    intervals.sort()\n    return intervals\n', visible='assert s.merge_intervals([(1,3),(2,4)])==[(1,4)]', checks=['assert s.merge_intervals([])==[]','assert s.merge_intervals([(5,7),(1,2),(2,5)])==[(1,7)]','assert s.merge_intervals([(1,10),(2,3),(12,13)])==[(1,10),(12,13)]','a=[(3,4),(1,2)]; assert s.merge_intervals(a)==[(1,2),(3,4)]; assert a==[(3,4),(1,2)]','assert s.merge_intervals([[1,2],[2,3]])==[(1,3)]','raises(ValueError,s.merge_intervals,[(3,1)])']),
 dict(id='10-topological-order', prompt='Repair topological_order(graph). graph maps a node to its dependency nodes. Return every key and dependency-only node once, placing all dependencies before their dependents. Raise ValueError for any cycle including a self-cycle. Do not mutate graph; any valid ordering is accepted.', code='def topological_order(graph):\n    return list(graph)\n', visible='r=s.topological_order({"b":["a"],"a":[]}); assert r.index("a")<r.index("b")', checks=['g={"a":["b","c"],"b":["d"],"c":["d"]}; r=s.topological_order(g); assert set(r)=={"a","b","c","d"} and len(r)==4; assert r.index("d")<r.index("b")<r.index("a"); assert r.index("d")<r.index("c")<r.index("a")','assert s.topological_order({})==[]','raises(ValueError,s.topological_order,{"a":["a"]})','raises(ValueError,s.topological_order,{"a":["b"],"b":["a"]})','g={"a":["b","b"]}; before=repr(g); r=s.topological_order(g); assert r==["b","a"] and repr(g)==before']),
 dict(id='11-atomic-json', prompt='Repair save_json(path,value): serialize JSON as UTF-8, write a temporary file in the destination directory, and atomically replace the destination only after the full serialized value is ready. On a serialization error preserve the old file byte-for-byte and leave no temporary file. Do not create missing directories. Use standard library only.', code='import json\ndef save_json(path, value):\n    with open(path,"w",encoding="utf-8") as f:\n        f.write(json.dumps(value))\n', visible='import tempfile,json; from pathlib import Path\nwith tempfile.TemporaryDirectory() as d:\n p=Path(d)/"x.json"; s.save_json(p,{"x":1}); assert json.loads(p.read_text())=={"x":1}', checks=['import tempfile,json; from pathlib import Path','with tempfile.TemporaryDirectory() as d:\n p=Path(d)/"x.json"; p.write_bytes(b"original bytes"); raises(TypeError,s.save_json,p,{"x":object()}); assert p.read_bytes()==b"original bytes"; assert sorted(x.name for x in Path(d).iterdir())==["x.json"]','with tempfile.TemporaryDirectory() as d:\n p=Path(d)/"x.json"; s.save_json(p,{"word":"café"}); assert json.loads(p.read_text())=={"word":"café"}','with tempfile.TemporaryDirectory() as d:\n p=Path(d)/"missing"/"x.json"; raises(FileNotFoundError,s.save_json,p,{})']),
 dict(id='12-retry-delay', prompt='Repair retry_delay(value, now, default=1.0), returning seconds to wait. Accept nonnegative numeric strings or RFC HTTP-date strings; now is a POSIX timestamp. For past dates, empty/invalid values, negative numbers, NaN or infinity return default. Never return less than default. Use standard library only.', code='def retry_delay(value, now, default=1.0):\n    try:\n        return float(value)\n    except (TypeError, ValueError):\n        return default\n', visible='assert s.retry_delay("5",0)==5', checks=['assert s.retry_delay("0",0,2)==2','assert s.retry_delay("-5",0,2)==2','assert s.retry_delay("nan",0,2)==2','assert s.retry_delay("inf",0,2)==2','assert s.retry_delay(None,0,3)==3','assert s.retry_delay("Thu, 01 Jan 1970 00:01:40 GMT",90,1)==10','assert s.retry_delay("Thu, 01 Jan 1970 00:01:40 GMT",110,2)==2'])
]
